import AppKit

/// Names every terminal window after its working directory's folder, unique
/// across all open windows.
///
/// The Dock menu's list of open windows is generated by AppKit from
/// `NSWindow.title` and can't be customized any other way, and shell-set titles
/// ("zsh", "user@host: ~") don't tell windows apart. So each window is titled:
///
/// - `KEA` — the folder name;
/// - `MEDI/KEA` — parent folders added when different folders share a name;
/// - `KEA ②` — a number when several windows (or tabs) are in the same folder,
///   the first-opened keeping the plain name;
/// - `ssh nas` — for a session tagged as SSH.
///
/// Windows without a known working directory keep their shell title.
@MainActor
final class WavettyWindowTitles {
    static let shared = WavettyWindowTitles()

    /// First-seen order per window, so numbering is stable as windows come and go.
    private var firstSeen: [ObjectIdentifier: Int] = [:]
    private var nextSeen = 0

    /// Names last applied, to skip no-op refreshes.
    private var lastNames: [ObjectIdentifier: String] = [:]
    private var refreshScheduled = false
    private var pollTimer: Timer?

    private init() {
        let nc = NotificationCenter.default
        for name in [NSWindow.didBecomeKeyNotification, NSWindow.willCloseNotification] {
            nc.addObserver(self, selector: #selector(windowsChanged(_:)), name: name, object: nil)
        }

        // Without shell integration (OSC 7) a `cd` produces no event — the pwd
        // is read from the OS on demand — so poll for folder changes. Cheap: a
        // few syscalls per window, and windows are re-titled only on change.
        pollTimer = Timer.scheduledTimer(withTimeInterval: 2, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.refreshIfChanged() }
        }
    }

    @objc private func windowsChanged(_ note: Notification) {
        setNeedsRefresh()
    }

    /// Re-title every terminal window on the next run-loop turn (coalesced).
    func setNeedsRefresh() {
        guard !refreshScheduled else { return }
        refreshScheduled = true
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            self.refreshScheduled = false
            self.lastNames = [:]
            self.refreshIfChanged()
        }
    }

    /// The title for `controller`'s window, or nil to keep the shell's title.
    func title(for controller: BaseTerminalController) -> String? {
        guard let window = controller.window, controller is TerminalController else { return nil }
        return computeNames(including: window)[ObjectIdentifier(window)]
    }

    private func refreshIfChanged() {
        let names = computeNames(including: nil)
        guard names != lastNames else { return }
        lastNames = names
        for window in NSApp.windows {
            (window.windowController as? TerminalController)?.wavettyRefreshTitle()
        }
    }

    // MARK: Naming

    private struct Candidate {
        let key: ObjectIdentifier
        let order: Int
        /// Standardized directory, or nil for an SSH session.
        let dir: String?
        let ssh: String?
    }

    /// Names for every visible terminal window (plus `extra`, which may not be
    /// visible yet while it's being set up).
    private func computeNames(including extra: NSWindow?) -> [ObjectIdentifier: String] {
        var candidates: [Candidate] = []
        var live: Set<ObjectIdentifier> = []
        for window in NSApp.windows {
            guard let controller = window.windowController as? TerminalController,
                  window.isVisible || window === extra else { continue }
            let key = ObjectIdentifier(window)
            live.insert(key)
            if firstSeen[key] == nil {
                firstSeen[key] = nextSeen
                nextSeen += 1
            }
            guard let surface = controller.wavettyTitleSurface else { continue }
            if let alias = SessionHistoryStore.shared.taggedSSHAlias(for: surface.id) {
                candidates.append(.init(key: key, order: firstSeen[key]!, dir: nil, ssh: alias))
            } else if let pwd = surface.effectivePwd() {
                let dir = (pwd as NSString).standardizingPath
                candidates.append(.init(key: key, order: firstSeen[key]!, dir: dir, ssh: nil))
            }
        }
        firstSeen = firstSeen.filter { live.contains($0.key) }

        let dirLabels = Self.uniqueFolderLabels(Set(candidates.compactMap(\.dir)))

        // Windows sharing a label (same folder, or same SSH host) get numbered
        // in first-seen order; the first keeps the plain name.
        var byLabel: [String: [Candidate]] = [:]
        for c in candidates {
            let label = c.ssh.map { "ssh \($0)" } ?? dirLabels[c.dir!]!
            byLabel[label, default: []].append(c)
        }
        var names: [ObjectIdentifier: String] = [:]
        for (label, group) in byLabel {
            for (i, c) in group.sorted(by: { $0.order < $1.order }).enumerated() {
                names[c.key] = i == 0 ? label : "\(label) \(Self.ordinal(i + 1))"
            }
        }
        return names
    }

    /// Shortest trailing-path label per directory that no other directory
    /// shares: `KEA`, or `MEDI/KEA` when another `…/KEA` is open.
    private static func uniqueFolderLabels(_ dirs: Set<String>) -> [String: String] {
        let home = NSHomeDirectory()
        func components(_ dir: String) -> [String] {
            if dir == home { return ["~"] }
            if dir == "/" { return ["/"] }
            let abbreviated = (dir as NSString).abbreviatingWithTildeInPath
            return abbreviated.split(separator: "/").map(String.init)
        }

        var depth: [String: Int] = Dictionary(uniqueKeysWithValues: dirs.map { ($0, 1) })
        func label(_ dir: String) -> String {
            let parts = components(dir)
            return parts.suffix(min(depth[dir]!, parts.count)).joined(separator: "/")
        }

        // Lengthen colliding labels until unique (or a label is the full path).
        while true {
            var byLabel: [String: [String]] = [:]
            for dir in dirs { byLabel[label(dir), default: []].append(dir) }
            var grew = false
            for group in byLabel.values where group.count > 1 {
                for dir in group where depth[dir]! < components(dir).count {
                    depth[dir]! += 1
                    grew = true
                }
            }
            if !grew { break }
        }
        return Dictionary(uniqueKeysWithValues: dirs.map { ($0, label($0)) })
    }

    /// ② ③ … ⑳, then (21), (22) …
    private static func ordinal(_ n: Int) -> String {
        guard (2...20).contains(n), let scalar = Unicode.Scalar(UInt32(0x2460 + n - 1)) else { return "(\(n))" }
        return String(Character(scalar))
    }
}
